// Lee la tarea recién creada en Recordatorios. Solo sigue si es "Crear mazo".
const it = $input.first().json;
const props = it.properties || {};

const readTitle = (p) => {
  if (!p) return '';
  if (Array.isArray(p.title)) return p.title.map(t => (t.plain_text || (t.text && t.text.content) || '')).join('');
  if (typeof p === 'string') return p;
  return '';
};
const readSelect = (p) => (p && p.select && p.select.name) || (typeof p === 'string' ? p : '');

const title = readTitle(props['Tarea']) || it['Tarea'] || it.name || '';
const tipo  = readSelect(props['Tipo']) || it['Tipo'] || '';

// Filtro: solo tareas de creación de mazo
if (tipo !== 'Crear mazo' && !/crear mazo/i.test(title)) return [];

// Extrae la materia del título: "🃏 Crear mazo de Antibióticos para Parcial Infecto"
let tema = '';
const m = title.match(/crear mazo de\s+(.+?)\s+para\b/i) || title.match(/crear mazo de\s+(.+)$/i);
if (m) tema = m[1].trim();
if (!tema) tema = readSelect(props['Materia']) || it['Materia'] || 'general';

// slug de carpeta en content/<slug>/notes.md
const slug = tema.toLowerCase()
  .normalize('NFD').replace(/[̀-ͯ]/g, '')
  .replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');

return [{ json: {
  taskPageId: it.id,
  tema, slug, title,
  GITHUB_RAW_BASE: it.GITHUB_RAW_BASE,
  FLASHCARDS_DB:   it.FLASHCARDS_DB,
  ANTHROPIC_MODEL: it.ANTHROPIC_MODEL,
  MAX_CARDS:       it.MAX_CARDS,
} }];

// Toma la respuesta de Claude (salida estructurada) y emite una carta por item.
const resp = $input.first().json;
const content = resp.content || [];
let txt = '';
for (const b of content) { if (b.type === 'text') txt += b.text; }
let cards = [];
try { cards = (JSON.parse(txt).cards) || []; }
catch (e) { throw new Error('No se pudo parsear el JSON de Claude: ' + e.message + ' | ' + txt.slice(0, 200)); }
const tema = $('Parsear tarea').item.json.tema;
return cards.map(c => ({ json: { front: c.front, back: c.back, tema } }));

// Una sola salida: marcar la tarea como Hecho con el número de cartas creadas.
const resp = $input.first().json;
const content = resp.content || [];
let txt = '';
for (const b of content) { if (b.type === 'text') txt += b.text; }
let n = 0; try { n = ((JSON.parse(txt).cards) || []).length; } catch (e) {}
return [{ json: { taskPageId: $('Parsear tarea').item.json.taskPageId, count: n } }];
